controls.action:
{(value) => {
          cancel()
          setState((s) => ({ ...s, tool: value as PdfCanvasTool, selected: null }))
        }}

{() => {
        close?.()
        setBlocksOpen(false)
        setRedactionOpen(false)
        setImagesOpen(false)
        setAnnotationsOpen(false)
        setFormsOpen(!formsOpen)
        if (!formsOpen) void runManualContentTool('list_form_fields', {})
      }}

{() => {
        close?.()
        setBlocksOpen(false)
        setRedactionOpen(false)
        setImagesOpen(false)
        setFormsOpen(false)
        setAnnotationsOpen(!annotationsOpen)
        if (!annotationsOpen) void runManualContentTool('read_annotations', {})
      }}

{() =>
              void runManualContentTool('add_note', {
                page: at + 1,
                text: noteDraft,
                x: noteX,
                y: noteY,
              })
            }

{() =>
                    void runManualContentTool('reply_note', {
                      page: at + 1,
                      note_id: noteId,
                      text: noteDraft,
                    })
                  }

{() =>
                    void runManualContentTool('edit_note', {
                      page: at + 1,
                      note_id: noteId,
                      text: noteDraft,
                    })
                  }

{() => {
                    setBlocksOpen(false)
                    setRedactionOpen(false)
                    setImagesOpen(false)
                    setFormsOpen(false)
                    setAnnotationsOpen(false)
                    setLocalMode(null)
                    setImageExportOpen(true)
                  }}

{() => {
                    setBlocksOpen(false)
                    setRedactionOpen(false)
                    setImagesOpen(false)
                    setFormsOpen(false)
                    setAnnotationsOpen(false)
                    setInsertMode(false)
                    setSelectTextMode(false)
                    setLocalMode('drawing')
                  }}

{() => {
                    setBlocksOpen(false)
                    setRedactionOpen(false)
                    setImagesOpen(false)
                    setFormsOpen(false)
                    setAnnotationsOpen(false)
                    setLocalOutputs([])
                    setLocalMode('pages')
                    void runManualContentTool('get_document_properties', {})
                  }}

{() => {
                          setSelected(image.imageUrl!)
                          onSelection({
                            url: image.imageUrl!,
                            title: image.title || `结果${index + 1}`,
                          })
                        }}

{() =>
            onApply({
              name: field.name,
              ...(field.type === 'checkbox' ? { checked } : { value: text }),
            })
          }

{(value) => {
                setName(value)
                setFeedback(null)
                const selected = snapshot.fields.find((item) => item.name === value)
                if (selected?.widgets[0]) onGotoPage(selected.widgets[0].page)
              }}

{(next) => {
                setError(null)
                setMaterial(null)
                if (next.size > 8 * 1024 * 1024) setError('图片不得超过8MiB，请重新选择')
                else if (!['image/png', 'image/jpeg'].includes(next.type))
                  setError('请选择 PNG 或 JPEG 图片')
                else setMaterial({ file: next, url: URL.createObjectURL(next) })
              }}

{(value) => {
            setTask({ key: targetKey, operation: value })
            setSource('upload')
            setError(null)
            setFeedback(null)
          }}

{(event) => {
            // The refresh button becomes disabled during the request. Keep
            // focus on the stable inspector so Escape still reaches it.
            event.currentTarget.closest<HTMLElement>('.mimir-pdf-inspector')?.focus()
            onRefresh()
          }}

{() =>
              void act('import_pages', {
                after_page: page,
                source_pages: sourceRange,
                assetFile: file,
              })
            }

{() =>
              void act('replace_pages', {
                pages: range,
                source_pages: sourceRange,
                assetFile: file,
              })
            }

{() => {
            try {
              const entries = outline.trim()
                ? outline
                    .split('\n')
                    .filter((s) => s.trim())
                    .map((s) => {
                      const m = /^( *)(\d+)\s*\|\s*(.+)$/.exec(s)
                      if (!m || m[1]!.length % 2)
                        throw new Error('请按“页码 | 标题”填写，层级用两个空格缩进')
                      return { page: Number(m[2]), title: m[3]!, level: m[1]!.length / 2 }
                    })
                : []
              setError(null)
              void act('set_outline', { entries })
            } catch (e) {
              setError(String(e))
            }
          }}

{(selectedFile) => {
            if (selectedFile.size > 50 * 1024 * 1024 || !selectedFile.size) {
              setError('请选择 50 MiB 以内的非空 PDF')
              return
            }
            setFile(selectedFile)
            setError(null)
          }}

{async () => {
                  try {
                    await navigator.clipboard.writeText(currentText)
                    setCopyStatus('已复制当前页识别文字')
                  } catch {
                    setCopyStatus('无法访问剪贴板，请选择下方文字后复制')
                  }
                }}

{(event) => {
                    const n = event.currentTarget.valueAsNumber
                    if (!Number.isFinite(n) || (field === 'width' && n < 4)) return
                    const rect =
                      field === 'width'
                        ? {
                            ...draft.rect!,
                            width: n,
                            height: (n * draft.rect!.height) / draft.rect!.width,
                          }
                        : { ...draft.rect!, [field]: n }
                    change({ ...draft, rect: clampSignature(rect, size) })
                  }}

{(e) => {
                const next = e.target.files?.[0]
                e.target.value = ''
                if (next) {
                  setFile(next)
                  void decode(next, mono)
                }
              }}

{(value) => {
              const block = blocks.find((item) => String(item.blockIndex) === value)
              if (block) onSelect(block)
            }}

stateHooks.initialValue:
{
    binding,
    text: fieldText(field),
    checked: field.value === true,
  }
